INSERT INTO `question` VALUES (11,'What is defined as the science of collecting, organizing, analyzing, and interpreting data?','Mathematics','Statistics','Calculus','Informatics','B',3,12,0),(12,'Which type of statistics uses sample data to make inferences or predictions about a population?','Descriptive Statistics','Ordinal Statistics','Inferential Statistics','Nominal Statistics','C',3,12,0),(13,'A numerical measurement made using a **Population** data set is called a...?','Statistic','Variable','Parameter','Sample','C',3,12,0),(14,'A numerical measurement made using a **Sample** data set is called a...?','Parameter','Statistic','Data','Population','B',3,12,0),(15,'Data that describes qualities such as colors or emotions and cannot be measured numerically is called?','Quantitative Data','Discrete Data','Continuous Data','Qualitative Data','D',3,12,0),(16,'Which variable type has no inherent order (e.g., Gender, Eye Color)?','Ordinal','Discrete','Nominal','Continuous','C',3,12,0),(17,'Which variable type has a clear rank or order (e.g., Education Level: High School < College)?','Nominal','Ordinal','Continuous','Parameter','B',3,12,0),(18,'Which type of variable is countable? (e.g., Number of books: $x = \\{1, 2, 3...\\}$)','Continuous','Qualitative','Discrete','Infinite','C',3,12,0),(19,'Which type of variable can assume any value on a line interval? (e.g., Temperature $T \\in \\mathbb{R}$)','Discrete','Nominal','Continuous','Ordinal','C',3,12,0),(20,'Given the dataset $x_i = \\{2, 6, 3, 1\\}$, calculate the summation $\\sum x_i$.','10','11','12','13','C',3,12,0),(21,'When data is collected in its original form, it is called...?','Raw Data','Grouped Data','Frequency Distribution','Class Limit','A',3,13,0),(22,'What is the term for organizing raw data into a table form using classes and frequencies?','Variable Analysis','Frequency Distribution','Data collection','Sampling','B',3,13,0),(23,'What is the formula for Percentage Frequency?','$\\frac{\\text{class frequency}}{\\text{sum of all frequency}} \\times 100\\%$','$\\frac{\\text{sum of all frequency}}{\\text{class frequency}} \\times 100\\%$','$\\text{class frequency} \\times 100$','$\\frac{\\text{class frequency}}{100}$','A',3,13,0),(24,'Which type of frequency distribution is used for nominal or ordinal-level data (e.g., Blood Type)?','Ungrouped Frequency Distribution','Grouped Frequency Distribution','Categorical Frequency Distribution','Continuous Frequency Distribution','C',3,13,0),(25,'Which type of frequency distribution is used when the range of data is small and can be enumerated (e.g., specific values 2, 3, 4)?','Categorical Frequency Distribution','Grouped Frequency Distribution','Ungrouped Frequency Distribution','Relative Frequency Distribution','C',3,13,0),(26,'Which type of frequency distribution is used when the range of data is very large?','Categorical Frequency Distribution','Ungrouped Frequency Distribution','Grouped Frequency Distribution','Nominal Frequency Distribution','C',3,13,0),(27,'What is the range of a dataset?','Lowest Value - Highest Value','Highest Value + Lowest Value','Highest Value - Lowest Value','(Highest Value + Lowest Value) / 2','C',3,13,0),(28,'What is the formula to estimate the number of classes using logarithms?','$1 + 3.3 \\log_{10} n$','$1 + 1.4 \\ln(n)$','Both A and B are correct','$1 + \\log_{10} n$','C',3,13,0),(29,'What is the Class Midpoint?','(Upper Class Limit - Lower Class Limit) / 2','(Upper Class Limit + Lower Class Limit) / 2','Upper Class Limit - Lower Class Limit','Upper Class Limit + Lower Class Limit','B',3,13,0),(30,'How do you find the Lower Class Boundary?','$\\text{Lower Class Limit} - 0.5$','$\\text{Lower Class Limit} + 0.5$','$\\text{Upper Class Limit} - 0.5$','$\\text{Lower Class Limit} \\times 0.5$','A',3,13,0),(31,'Which statistical measure reflects the center of a data distribution?','Standard Deviation','Central Tendency','Variance','Range','B',3,14,0),(32,'Which Greek letter represents the mean of a **Population**?','$\\sigma$','$\\bar{y}$','$\\mu$','$n$','C',3,14,0),(33,'Calculate the Arithmetic Mean of this dataset: $y_i = \\{4, 1, 3, 5, 3, 2, 3\\}$ ($n=7$).','2','4','3','3.5','C',3,14,0),(34,'According to the properties of the Arithmetic Mean, what is the value of $\\sum(y_i - \\bar{y})$?','1','0','$\\infty$','$n$','B',3,14,0),(35,'Calculate the **Geometric Mean** of the numbers 2 and 18 ($\\bar{G} = \\sqrt{2 \\times 18}$).','20','10','6','9','C',3,14,0),(36,'Which formula represents the **Harmonic Mean** for ungrouped data?','$\\bar{H} = \\frac{\\sum y_i}{n}$','$\\bar{H} = \\frac{n}{\\sum (1/y_i)}$','$\\bar{H} = \\sqrt{\\frac{\\sum y_i^2}{n}}$','$\\bar{H} = \\sqrt[n]{y_1 \\times ... \\times y_n}$','B',3,14,0),(37,'Which formula represents the **Quadratic Mean** for ungrouped data?','$\\bar{Q} = \\sqrt{\\frac{\\sum y_i^2}{n}}$','$\\bar{Q} = \\frac{n}{\\sum y_i}$','$\\bar{Q} = \\frac{\\sum f_i y_i}{\\sum f_i}$','$\\bar{Q} = \\frac{\\sum y_i}{n}$','A',3,14,0),(38,'In a Grouped Frequency Distribution, what is the formula for the Arithmetic Mean?','$\\bar{y} = \\frac{\\sum f_i}{\\sum f_i y_i}$','$\\bar{y} = \\sum f_i y_i$','$\\bar{y} = \\frac{\\sum f_i y_i}{\\sum f_i}$','$\\bar{y} = \\frac{\\sum y_i}{n}$','C',3,14,0),(39,'If a constant real number ($a$) is added to every observation ($x_i = y_i + a$), what happens to the new mean ($\\bar{x}$)?','$\\bar{x} = \\bar{y} \\times a$','$\\bar{x} = \\bar{y} + a$','$\\bar{x} = \\bar{y} - a$','The mean stays the same','B',3,14,0),(40,'Which mean is calculated by taking the $n$-th root of the product of values? ($\\bar{G} = \\sqrt[n]{y_1 \\times ... \\times y_n}$)','Harmonic Mean','Arithmetic Mean','Quadratic Mean','Geometric Mean','D',3,14,0),(41,'What is the primary purpose of using statistical graphs?','To make the data set harder to read','To convey data to viewers in pictorial form','To replace the need for data collection','To hide trends in the data','B',3,15,0),(42,'Which type of graph represents data categories as proportional parts of a circle?','Histogram','Bar Graph','Stem-and-Leaf Plot','Pie Diagram (Circle Graph)','D',3,15,0),(43,'What must be prepared before you can create a pie chart?','A range calculation','A relative frequency table','A stem-and-leaf plot','A physicsaptitude test','B',3,15,0),(44,'Bar charts are primarily used to display which types of data?','Continuous data only','Categorical or discrete numerical data','Only infinite populations','Only mathematical notations','B',3,15,0),(45,'In a frequency histogram, what does the horizontal scale measure?','The frequencies of the classes','The names of the categories','The quantitative data values','The total number of students','C',3,15,0),(46,'Which of the following is a mandatory requirement for the bars in a Histogram?','The bars must never touch','The bars must be different colors','Consecutive bars must touch','The bars must be circular','C',3,15,0),(47,'What are the numbers called that separate histogram classes without forming gaps?','Class Midpoints','Class Parameters','Class Boundaries','Class Statistics','C',3,15,0),(48,'A stem-and-leaf plot separates a number into a \'stem\' (leftmost digits) and a \'leaf\'. What is the leaf?','The entry\'s leftmost digits','The entry\'s rightmost digit','The average of the digits','The sum of the digits','B',3,15,0),(49,'The stem-and-leaf plot is an example of which type of data analysis?','Inferential data analysis','Exploratory data analysis','Hypothesis testing','Parameter measurement','B',3,15,0),(50,'Given a stem-and-leaf plot key of $1|8 = 18$, what value is represented by a stem of $3$ and a leaf of $2$?','3.2','5','32','1832','C',3,15,0),(51,'Which measure of central tendency represents the middle value when data is arranged in order?','Mean','Median','Mode','Standard Deviation','B',3,16,0),(52,'How is the Median often denoted in statistical notation?','$Mo$','$Me$','$\\mu$','$\\bar{y}$','B',3,16,0),(53,'Calculate the median for the following raw data: $\\{1, 2, 3, 3, 3, 4, 5\\}$ ($n=7$).','2','4','3','3.5','C',3,16,0),(54,'If a dataset has an even number of observations ($n=10$), how is the median calculated?','The 5th observation','The 6th observation','The mean of the 5th and 6th observations','The sum of all observations divided by 10','C',3,16,0),(55,'Which of the following is a key property of the Median?','It is highly affected by extreme values','It is not affected by extreme values','It is always equal to the Mean','It can only be used for nominal data','B',3,16,0),(56,'In the grouped median formula $Me = L_1 + [ \\frac{(\\sum f_i / 2) - F_i}{f_i} ] \\times W$, what does $W$ represent?','Frequency of the median class','Lower limit of the median class','Cumulative frequency','Width of the median class','D',3,16,0),(57,'What is defined as the value that appears with the greatest frequency in a data set?','Mean','Median','Mode','Range','C',3,16,0),(58,'If a data set has exactly two values that occur with the same highest frequency, it is called...?','Unimodal','Bimodal','Multimodal','Nomodal','B',3,16,0),(59,'What is the mode of the following dataset: $\\{1, 2, 3, 6, 7, 8, 9, 10\\}$?','1','10','5.5','No Mode','D',3,16,0),(60,'Which measure of central tendency is the only one that can be used with nominal-level data?','Arithmetic Mean','Geometric Mean','Median','Mode','D',3,16,0),(111,'What does the term ICT stand for?','Information and Computer Technology','Information and Communication Technology','Informatics and Communication Tools','Internal Computing Technology','B',8,7,0),(112,'According to the text, ICT refers to the convergence of which two networks?','Social and Business','Satellite and Radio','Audio-visual and Telephone','Hardware and Software','C',8,7,0),(113,'How is a \'computer\' defined in the text?','A machine that only performs math','An electronic machine capable of performing instructions in memory','A totality of software components','A mechanical counting device','B',8,7,0),(114,'Which computer classification was introduced with the advent of single-chip microprocessors?','Mainframes','Supercomputers','Microcomputers','Hybrid computers','C',8,7,0),(115,'What was the name of the best-known early microcomputer introduced in 1975?','Macintosh','Altair 8800','Difference Engine','DECVAX','B',8,7,0),(116,'Small handheld computers with limited hardware like PDAs are classified as...','Mainframes','Mobile devices','Supercomputers','Mini computers','B',8,7,0),(117,'Which type of computer is also known as a \'Midrange Computer\'?','Mainframe','Microcomputer','Supercomputer','Mini computer','D',8,7,0),(118,'Mainframe computer performance is typically measured in which unit?','FLOPS','MIPS','PPM','KVM','B',8,7,0),(119,'Which type of computer is designed for intense numerical calculations like weather forecasting?','Digital Computer','Supercomputer','Analog Computer','Mini computer','B',8,7,0),(120,'Supercomputer processing speeds are measured in...','MIPS','RPM','FLOPS','VDU','C',8,7,0),(121,'Who devised the first adding machine in 1642?','Charles Babbage','Blaise Pascal','Gottfried Wilhelm Leibniz','Herman Hollerith','B',8,7,0),(122,'Which 19th-century inventor is considered the pioneer of the modern digital computer?','Herman Hollerith','Ada Byron','Charles Babbage','Joseph-Marie Jacquard','C',8,7,0),(123,'Which technology was the core of First Generation (1940-1956) computers?','Transistors','Integrated Circuits','Vacuum Tubes','Microprocessors','C',8,7,0),(124,'Second Generation computers (1956-1963) replaced vacuum tubes with...','Transistors','Silicon Chips','Superconductors','Punch cards','A',8,7,0),(125,'What was the hallmark technology of Third Generation computers?','Vacuum Tubes','Integrated Circuits','Microprocessors','Artificial Intelligence','B',8,7,0),(126,'The Intel 4004 chip, developed in 1971, ushered in which computer generation?','Second','Third','Fourth','Fifth','C',8,7,0),(127,'Which generation of computing is based on Artificial Intelligence (AI)?','Third','Fourth','Fifth','Sixth','C',8,7,0),(128,'Which type of computer measures physical magnitudes such as temperature and pressure?','Digital Computer','Analog Computer','Hybrid Computer','Mainframe','B',8,7,0),(129,'Which type of computer operates essentially by counting and accepts data as discrete items?','Analog Computer','Digital Computer','Hybrid Computer','Mechanical Loom','B',8,7,0),(130,'A computer system that is a mixture of both analog and digital components is called?','Microcomputer','Mainframe','Hybrid Computer','Supercomputer','C',8,7,0),(131,'Which part of the computer is described as the collection of tangible physical components?','Software','Firmware','Hardware','Middleware','C',8,7,0),(132,'Which type of memory is volatile and stores data temporarily for the CPU?','ROM','Hard Disk','RAM','DVD','C',8,7,0),(133,'What is the \'fundamental core\' of a computer that controls hardware and loads applications?','Word Processor','Operating System','Utility Program','Database','B',8,7,0),(134,'What is the technology that allows an OS to use multiple processors simultaneously to improve performance?','Multitasking','Clustering','Multiprocessing','Multithreading','C',8,7,0),(135,'Which translation program translates the whole source program into machine code before execution?','Interpreter','Assembler','Compiler','Utility','C',8,7,0),(137,'Which of the following is classified as a \'Need\' (basic necessity for survival)?','Bigger homes','iPhones','Shelter','Luxury Cars','C',5,3,0),(138,'What is defined as the \'best alternative that we forgo\' when we make a choice?','Sunk cost','Marginalism','Opportunity cost','Factor of production','C',5,3,0),(139,'Costs that have already been incurred and cannot be avoided regardless of future actions are...','Marginal costs','Opportunity costs','Economic goods','Sunk costs','D',5,3,0),(140,'Which branch of economics examines the behavior of economic aggregates like income and output on a national scale?','Microeconomics','Macroeconomics','Socioeconomics','Global economics','B',5,3,0),(141,'What are the three categories of scarce resources identified in the Economic Problem?','Wants, Needs, Choices','Land, Labor, Capital','Money, Banks, Firms','Income, Output, Spending','B',5,3,0),(142,'To an economist, why are all goods and services that have a price considered relatively scarce?','Because they are only found in poor countries','Because they are expensive to ship','Because they are scarce relative to people\'s demand','Because nature no longer provides them','C',5,3,0),(143,'Which factor of production refers to \'physical and mental effort of people used in production\'?','Land','Capital','Labor','Enterprise','C',5,3,0),(144,'Which economic activity involves the process of transforming scarce resources into useful goods?','Consumption','Production','Exchange','Distribution','B',5,3,0),(145,'Which activity is described as the \'link between consumer and producer\'?','Consumption','Production','Exchange','Distribution','C',5,3,0),(146,'What is the main difference between \'Economic Goods\' and \'Free Goods\'?','Economic goods are free; Free goods have a price','Economic goods are naturally abundant','Economic goods require human effort to obtain','Free goods are scarce relative to demand','C',5,3,0),(147,'In the concept of Marginalism, a firm deciding to produce more output considers only the ____ cost.','Sunk','Total','Additional (Marginal)','Initial','C',5,3,0),(148,'What is defined as the number of units of a product that a household would buy in a given time period at the current market price?','Quantity Demanded','Demand Schedule','The Wealth Factor','Market Equilibrium','A',5,4,0),(149,'A table showing how much of a given product a household would be willing to buy at different prices is called a...','Demand Curve','Demand Schedule','Price List','Supply Ledger','B',5,4,0),(150,'According to the Law of Demand, what is the relationship between price and the quantity demanded?','Positive relationship','Direct relationship','Negative (inverse) relationship','No relationship','C',5,4,0),(151,'Because of the Law of Demand, what is the typical direction of a demand curve slope?','Downward','Upward','Horizontal','Vertical','A',5,4,0),(152,'If the demand for a product goes UP when income is higher, that product is classified as a...','Inferior Good','Normal Good','Substitute Good','Complementary Good','B',5,4,0),(153,'What happens to the demand for an **Inferior Good** when income rises?','Demand increases','Demand stays the same','Demand falls','Price increases','C',5,4,0),(154,'If the price of one good increases and the demand for another good goes UP, these two goods are...','Complements','Normal Goods','Substitutes','Inferior Goods','C',5,4,0),(155,'Which of the following describes **Complements**?','Goods that can serve as replacements','Goods that have no relation to price','Goods that are only for poor countries','Goods that \'go together\' like bread and butter','D',5,4,0),(156,'If consumers expect an increase in their income or higher prices in the future, what usually happens?','An increase in current demand','A decrease in current demand','Demand shifts to the left','No change in behavior','A',5,4,0),(157,'A change in the **Price** of a good or service leads to which of the following?','A shift of the demand curve','Movement along the demand curve','An increase in the number of buyers','A change in tastes and preferences','B',5,4,0),(158,'A change in income, preferences, or prices of **related** goods leads to...','Movement along the curve','A shift of the entire demand curve','A change in quantity demanded','No change in the graph','B',5,4,0),(159,'When the demand curve shifts to the **Right**, this indicates that...','Demand has decreased','Demand has increased','Price has decreased','Quantity demanded is zero','B',5,4,0),(160,'How is **Profit** defined in economics?','The sum of all sales','The difference between revenues and costs','The total amount of cash in a bank','The price of a product multiplied by quantity','B',5,5,0),(161,'What does **Quantity Supplied** represent?','The number of units a household wants to buy','The total inventory in a warehouse','The number of units a firm is willing and able to offer for sale at a particular price','The cost of production','C',5,5,0),(162,'A table showing how much of a product firms will supply at different prices is called a...','Demand Schedule','Supply Curve','Supply Schedule','Production Ledger','C',5,5,0),(163,'According to the **Law of Supply**, what is the relationship between price and quantity supplied?','Negative relationship','Inverse relationship','Positive relationship','No relationship','C',5,5,0),(164,'Because of the Law of Supply, supply curves typically have a ____ slope.','Negative','Positive','Horizontal','Vertical','B',5,5,0),(165,'How are **Input Prices** (costs) related to Supply?','Positively related','Negatively related','Not related','Only related in the long run','B',5,5,0),(166,'What effect does an **advance in technology** typically have on supply?','Decrease in supply','Increase in supply','No change in supply','Supply curve becomes vertical','B',5,5,0),(167,'If firms expect higher prices in the future, what happens to the **current** supply?','Current supply increases','Current supply decreases','Current supply stays the same','Current supply becomes zero','B',5,5,0),(168,'An increase in the **number of sellers** in a market results in...','A decrease in market supply','An increase in market supply','A movement along the curve','Higher input prices','B',5,5,0),(169,'A change in the **Price** of a good leads to which of the following?','A shift of the supply curve','A change in the number of sellers','Movement along the supply curve','A change in technology','C',5,5,0),(170,'A change in costs, input prices, or technology leads to...','Movement along the curve','A shift of the entire supply curve','A change in quantity demanded','No change in the graph','B',5,5,0),(171,'When the supply curve **shifts to the right**, this indicates that...','Supply has decreased','Supply has increased','Price has decreased','The number of buyers increased','B',5,5,0),(172,'What condition exists when quantity supplied ($Q_s$) and quantity demanded ($Q_d$) are equal?','Excess Demand','Market Equilibrium','Excess Supply','Market Shortage','B',5,6,0),(173,'At market equilibrium, what is the tendency for the market price to change?','Price tends to rise','Price tends to fall','There is no tendency for the price to change','Price changes randomly','C',5,6,0),(174,'Which term describes the condition that exists when quantity demanded exceeds quantity supplied at the current price?','Excess Supply','Surplus','Excess Demand','Equilibrium','C',5,6,0),(175,'When quantity demanded exceeds quantity supplied, what happens to the price until equilibrium is restored?','Price tends to fall','Price tends to rise','Price stays the same','Price becomes zero','B',5,6,0),(176,'Which term is another name for **Excess Supply**?','Shortage','Equilibrium','Scarcity','Surplus','D',5,6,0),(177,'In a condition of **Excess Supply**, what is the relationship between $Q_s$ and $Q_d$?','$Q_s < Q_d$','$Q_s = Q_d$','$Q_s > Q_d$','$Q_s = 0$','C',5,6,0),(178,'When quantity supplied exceeds quantity demanded, the price tends to ____ until equilibrium is restored.','Rise','Fall','Stay constant','Shift the curve','B',5,6,0),(179,'To find the equilibrium price using equations, which condition must be satisfied?','$Q_d = 0$','$Q_s = 0$','$Q_d = Q_s$','$Q_d > Q_s$','C',5,6,0),(180,'Given the equations $Q_d = 50 - 6P$ and $Q_s = 4P$, what is the calculated equilibrium price ($P$)?','P = 10','P = 20','P = 5','P = 50','C',5,6,0),(181,'Using the equilibrium price of $P = 5$ in the equation $Q_s = 4P$, what is the equilibrium quantity ($Q$)?','Q = 20','Q = 10','Q = 50','Q = 15','A',5,6,0),(182,'On a supply and demand graph, what does the point \'E\' represent?','Maximum Price','Minimum Supply','The Intersection (Equilibrium)','The Shortage Point','C',5,6,0),(183,'If the market price is set at a level where $Q_s$ is 25 and $Q_d$ is 9, what is the resulting surplus?','16 units','34 units','9 units','25 units','A',5,6,0),(319,'What is the decimal form of the rational number $7/4$?','$1.25$','$1.75$','$0.75$','$1.4$','B',4,9,0),(320,'Which inequality represents the interval $[-1, 4)$?','$-1 < x \\le 4$','$-1 \\le x < 4$','$-1 \\le x \\le 4$','$-1 < x < 4$','B',4,9,0),(321,'Expand the algebraic expression $2(3x + 5)$.','$6x + 5$','$6x + 10$','$3x + 10$','$5x + 7$','B',4,9,0),(322,'Calculate the value of $3$ to the power of $3$ ($3^3$).','$6$','$9$','$27$','$81$','C',4,9,0),(323,'Evaluate the absolute value $|-12|$.','$-12$','$12$','$0$','$1$','B',4,9,0),(324,'Find the distance between $-2$ and $5$ on the real number line.','$3$','$7$','$-7$','$-3$','B',4,9,0),(325,'Calculate the distance between the points $(1, 1)$ and $(4, 5)$ in the coordinate plane.','$5$','$7$','$25$','$6$','O',4,9,0),(326,'Find the midpoint of the line segment with endpoints $-6$ and $2$ on the number line.','$-4$','$-2$','$2$','$4$','B',4,9,0),(327,'Find the coordinates of the midpoint of the segment connecting $(0, 0)$ and $(6, 8)$.','$(3, 4)$','$(6, 8)$','$(2, 3)$','$(12, 16)$','O',4,9,0),(328,'Solve the linear equation $5x = 20$ for $x$.','$4$','$5$','$100$','$15$','O',4,9,0),(329,'Solve the linear inequality $-3x \\le 12$.','$x \\le -4$','$x \\ge -4$','$x < 4$','$x > -4$','B',4,9,0),(330,'Solve the quadratic equation $(x - 3)^2 = 4$.','$5$ and $1$','$7$ and $-1$','$3$ and $-3$','$2$ and $-2$','O',4,9,0),(331,'Solve the quadratic equation $x^2 - 3x - 4 = 0$.','$4$ and $-1$','$-4$ and $1$','$2$ and $-2$','$3$ and $1$','O',4,9,0),(332,'Evaluate the expression $2^{-3}$.','$-8$','$1/6$','$1/8$','$8$','C',4,9,0),(333,'Calculate the sum: $(-5) + (-7)$.','$-2$','$2$','$-12$','$12$','C',4,9,0),(334,'Find the derivative of the function $f(x) = 16t^2$.','$16t$','$32t$','$32$','$16t^2$','B',4,17,0),(335,'Calculate the derivative of $f(x) = \\frac{x}{x - 1}$.','$\\frac{-1}{(x - 1)^2}$','$\\frac{1}{(x - 1)^2}$','$\\frac{x}{(x - 1)^2}$','$1$','O',4,17,0),(336,'What is the derivative of $f(x) = \\sqrt{x}$ for $x > 0$?','$\\frac{1}{2\\sqrt{x}}$','$2\\sqrt{x}$','$\\frac{1}{\\sqrt{x}}$','$x^{1/2}$','O',4,17,0),(337,'Differentiate the function $y = x^3 - 3x^2 + 2$.','$3x^2 - 6x$','$3x^2 - 3x$','$x^2 - 6x$','$3x^2 - 6$','O',4,17,0),(338,'Find the second derivative ($y\'\'$) of the function $y = x^3$.','$3x^2$','$6x$','$6$','$0$','B',4,17,0),(339,'If $f(x) = 5 \\sin(x)$, what is $f\'(x)$?','$5 \\sin(x)$','$-5 \\cos(x)$','$5 \\cos(x)$','$-5 \\sin(x)$','C',4,17,0),(340,'Find the derivative of $y = \\cos(x)$.','$\\sin(x)$','$-\\sin(x)$','$\\cos(x)$','$-\\cos(x)$','B',4,17,0),(341,'Calculate the derivative of $y = x^2 \\sin(x)$ using the Product Rule.','$2x \\sin(x)$','$x^2 \\cos(x)$','$2x \\sin(x) + x^2 \\cos(x)$','$2x \\cos(x)$','C',4,17,0),(342,'What is the derivative of $y = \\tan(x)$?','$\\cos^2(x)$','$\\csc^2(x)$','$\\sec(x) \\tan(x)$','$\\sec^2(x)$','D',4,17,0),(343,'Find the derivative of the exponential function $f(x) = 5e^x$.','$5e^x$','$5xe^{x-1}$','$e^x$','$5$','O',4,17,0),(344,'Differentiate $y = 2^x$.','$x \\cdot 2^{x-1}$','$2^x$','$2^x \\ln(2)$','$\\frac{2^x}{\\ln(2)}$','C',4,17,0),(345,'Find the derivative of $y = \\ln(x^2)$.','$\\frac{1}{x^2}$','$\\frac{2}{x}$','$2x$','$\\frac{1}{2x}$','B',4,17,0),(346,'Calculate the derivative of $y = \\log_{10}(x)$.','$\\frac{1}{x}$','$\\frac{1}{x \\ln(10)}$','$\\frac{\\ln(10)}{x}$','$x \\ln(10)$','B',4,17,0),(347,'Using the Chain Rule, find the derivative of $y = \\sin(x^2 + x)$.','$\\cos(x^2 + x)$','$(2x + 1) \\cos(x^2 + x)$','$(2x + 1) \\sin(x^2 + x)$','$\\cos(2x + 1)$','B',4,17,0),(348,'Find the derivative of $y = (3x - 2)^{-1}$.','$-3(3x - 2)^{-2}$','$-1(3x - 2)^{-2}$','$3(3x - 2)^{-2}$','$-3(3x - 2)^{-1}$','O',4,17,0),(349,'Calculate the third derivative ($y\'\'\'$) of $y = x^4$.','$4x^3$','$12x^2$','$24x$','$24$','C',4,17,0),(350,'Find the derivative of $y = e^{-x}$.','$e^{-x}$','$-e^{-x}$','$xe^{-x-1}$','$-x e^{-x}$','B',4,17,0),(351,'Differentiate $y = \\sec(x)$.','$\\sec(x) \\tan(x)$','$\\sec^2(x)$','$\\tan(x)$','$-\\csc(x) \\cot(x)$','B',4,17,0),(352,'Find the derivative of the constant function $f(x) = \\pi^2$.','$2\\pi$','$\\pi$','$1$','$0$','D',4,17,0),(353,'Calculate the derivative of $y = \\frac{\\sin(x)}{x}$.','$\\frac{x \\cos(x) - \\sin(x)}{x^2}$','$\\frac{\\sin(x) - x \\cos(x)}{x^2}$','$\\frac{\\cos(x)}{1}$','$\\frac{x \\sin(x) - \\cos(x)}{x^2}$','O',4,17,0),(389,'How is Economics defined?','The study of how people make infinite money','The study of how societies use scarce resources','The study of how to build bigger homes','The study of international iphones','B',5,3,0);
