INSERT INTO `site_info` VALUES (1,'about','About Us','<h2 style=\"margin-bottom: 1.5rem;\">Hi, I&#39;m Havin!</h2>\r\n\r\n<p class=\"lead\">I&rsquo;m a student at the <strong>University of Sulaimani</strong> studying <span style=\"color: var(--primary-color); font-weight: bold;\">Statistics and Informatics</span>.</p>\r\n\r\n<p>I created <strong>StatInfoProject</strong> to solve two simple problems: I needed a better way to collect data for my projects, and I wanted to give my fellow students a place to study and take practice exams outside of our regular university hours.</p>\r\n\r\n<hr style=\"margin: 2rem 0; opacity: 0.1;\" />\r\n<h3>Acknowledgments</h3>\r\n\r\n<p>This project started as a small idea of mine, but it became much bigger and better with the help of my friends:</p>\r\n\r\n<blockquote><strong>Special Thanks to:</strong><br />\r\nDyary Muhammad, Aland Ranjdar, Ahmad Ghazi, Ara Ahmad, and Ballen Jalal.</blockquote>\r\n\r\n<div style=\"margin-top: 2rem; padding: 1.5rem; background-color: rgba(0,0,0,0.03); border-radius: 12px; text-align: center;\">\r\n<p style=\"margin-bottom: 1rem;\">I hope this tool helps you in your studies! If you run into any issues or have questions, feel free to reach out.</p>\r\n<a class=\"btn btn-primary\" href=\"mailto:havinmas3ud@gmail.com\" style=\"text-decoration: none; color: white; padding: 10px 20px; border-radius: 8px; display: inline-block;\">Email Me </a></div>\r\n','2026-01-22 17:04:52');
/*!40000 ALTER TABLE `site_info` ENABLE KEYS */;
UNLOCK TABLES;

