INSERT INTO `subject` VALUES (3,'Statistics ','Statistics-101','the science of collecting, organizing, analyzing, interpreting, and presenting data to find meaningful insights.',1),(4,'Mathematics','Math-101','the abstract science of structure, quantity, space, and change, using logical reasoning and precise language to find patterns, solve problems, and describe the world, from basic counting and shapes (geometry) to complex concepts (algebra, calculus) and their applications in science, engineering, finance, and technology.',1),(5,'Economics','Eco-101','explains how societies manage scarce resources (land, labor, capital, enterprise) to produce, distribute, and consume goods/services.',1),(8,'ICT','ict-101','a broad term for all digital tools, systems, and infrastructure used to create, process, store, transmit, and share information, including hardware (computers, smartphones), software, the internet, networks, and telecommunication devices (phones, radio, TV).',1);
